from typing import List

def criticalConnections(V: int, adj: List[List[int]]) -> List[List[int]]:
    # Initialize variables for Tarjan's algorithm
    disc = [0] * V
    low = [0] * V
    time = 1
    visited = [False] * V
    critical = []

    def dfs(u, parent):
        nonlocal time
        visited[u] = True
        disc[u] = low[u] = time
        time += 1

        for v in adj[u]:
            if not visited[v]:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    critical.append([min(u, v), max(u, v)])
            elif v != parent:
                low[u] = min(low[u], disc[v])

    for u in range(V):
        if not visited[u]:
            dfs(u, -1)

